# Name another person on the sheet as the person's patron. Validate the body before touching the store, so a refusal writes nothing.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: patron
patron:
  class: net.officefloor.hq.app.person.ValidatePatron
  next: viewer
viewer:
  class: net.officefloor.hq.app.access.RefuseViewer
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.person.AddPatron
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPatronAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
-- A person's patrons: other people on the same sheet they have named, each at most once.
CREATE TABLE person_patron (
    person_id BIGINT NOT NULL REFERENCES person (id),
    patron_id BIGINT NOT NULL REFERENCES person (id),
    PRIMARY KEY (person_id, patron_id)
);
package net.officefloor.hq.app.person;

import java.util.stream.Stream;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Names another person on the sheet as the person's patron; refuses the person themselves and a patron they have already. */
public class AddPatron {
    public void add(@Val PatronInput input, @Val Person person, PersonRepository repository, Out<PatronAdded> added)
            throws BadRequestException {
        Person patron = repository.find(person.getSheetId(), input.patronId());
        if (patron == null) {
            throw new BadRequestException("No such person on this sheet");
        }
        if (patron.getId() == person.getId()) {
            throw new BadRequestException("A person cannot be their own patron");
        }
        if (!repository.addPatron(person.getId(), patron.getId())) {
            throw new BadRequestException(patron.getName() + " is already a patron; reload the sheet");
        }
        person.setPatrons(Stream.concat(person.getPatrons().stream(), Stream.of(patron.getName())).sorted().toList());
        added.set(new PatronAdded(patron));
    }
}
package net.officefloor.hq.app.person;

/** The patron just added to the person. */
public record PatronAdded(Person patron) {
}
package net.officefloor.hq.app.person;

/** A validated patron to add: the id of the person named as patron. */
public record PatronInput(long patronId) {
}
package net.officefloor.hq.app.person;

/** The id of the person to name as a patron, and the signed-in user (`by`) doing it. */
public record PatronRequest(Long patron, String by) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

public class RecordPatronAdded {
    public void record(@Val Person person, @Val PatronAdded added, @Val ChangedBy by, Audit audit) {
        audit.record("PATRON_ADDED sheet=" + person.getSheetId() + " by=" + by.name() + " name=" + person.getName()
                + " patron=" + added.patron().getName());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Which person to name as patron. Publishes it, with the user making the change. */
public class ValidatePatron {
    public void validate(@RequestBody PatronRequest request, Out<PatronInput> patron, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        if (request == null || request.patron() == null) {
            throw new BadRequestException("Choose a patron");
        }
        patron.set(new PatronInput(request.patron()));
        changedBy.set(by);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;

/** Refuses adding a person whose name is already in use on the sheet, or whose contact another person has. */
public class CheckPersonName {
    public void check(@Val SheetResponse sheet, @Val PersonRequest request, PersonRepository repository)
            throws BadRequestException {
        if (repository.nameTaken(sheet.id(), request.name(), null)) {
            throw new BadRequestException(PersonRepository.NAME_TAKEN);
        }
        if (repository.contactTaken(sheet.id(), request.contactOrNull(), null)) {
            throw new BadRequestException(PersonRepository.CONTACT_TAKEN);
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;

/** Refuses renaming a person to a name another person on the sheet already has, or giving them a contact another person has. */
public class CheckPersonRename {
    public void check(@Val SheetResponse sheet, @Val PersonRequest request, @Val Person person,
            PersonRepository repository) throws BadRequestException {
        if (repository.nameTaken(sheet.id(), request.name(), person.getId())) {
            throw new BadRequestException(PersonRepository.NAME_TAKEN);
        }
        if (repository.contactTaken(sheet.id(), request.contactOrNull(), person.getId())) {
            throw new BadRequestException(PersonRepository.CONTACT_TAKEN);
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;

/** The rule for a person's name, shared by every form that names a person. */
public final class PersonName {

    private PersonName() {
    }

    /** A person's name, trimmed: required, at most 200 characters. */
    public static String of(String typed) throws BadRequestException {
        String name = typed == null ? "" : typed.trim();
        if (name.isEmpty()) {
            throw new BadRequestException("Enter a name");
        }
        if (name.length() > 200) {
            throw new BadRequestException("A name is at most 200 characters");
        }
        return name;
    }
}

