                    + " (SELECT 1 FROM person_patron WHERE person_id = ? AND patron_id = ?)",
                    personId, patronId, personId, patronId) == 1;
        } catch (DuplicateKeyException e) {
            return false;
        }
    }

    /** Sets each person's patrons' names, sorted, their grades and their holds. */
    private List<Person> withPatrons(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return people;
        }
        Map<Long, List<GradeFrom>> grades = jdbc.query(
                "SELECT g.person_id, g.grade, g.from_date FROM person_grade g JOIN person q ON q.id = g.person_id"
                        + " WHERE q.sheet_id = ?",
                (rs, n) -> Map.entry(rs.getLong("person_id"), GRADE.mapRow(rs, n)), sheetId).stream()
                .collect(Collectors.groupingBy(Map.Entry::getKey,
                        Collectors.mapping(Map.Entry::getValue, Collectors.toList())));
        for (Person person : people) {
            person.setGrades(grades.getOrDefault(person.getId(), List.of()));
        }
        Map<Long, List<HoldSpan>> holds = jdbc.query(
                "SELECT h.person_id, h.from_date, h.to_date FROM person_hold h JOIN person q ON q.id = h.person_id"
                        + " WHERE q.sheet_id = ? ORDER BY h.id",
                (rs, n) -> Map.entry(rs.getLong("person_id"), new HoldSpan(rs.getObject("from_date", LocalDate.class),
                        rs.getObject("to_date", LocalDate.class))), sheetId).stream()
                .collect(Collectors.groupingBy(Map.Entry::getKey,
                        Collectors.mapping(Map.Entry::getValue, Collectors.toList())));
        for (Person person : people) {
            person.setHolds(holds.getOrDefault(person.getId(), List.of()));
        }
        Map<Long, List<String>> patrons = jdbc.query(
                "SELECT pp.person_id, q.name FROM person_patron pp JOIN person q ON q.id = pp.patron_id"
                        + " WHERE q.sheet_id = ?",
                (rs, n) -> Map.entry(rs.getLong("person_id"), rs.getString("name")), sheetId).stream()
                .collect(Collectors.groupingBy(Map.Entry::getKey,
                        Collectors.mapping(Map.Entry::getValue, Collectors.toList())));
        for (Person person : people) {
            person.setPatrons(patrons.getOrDefault(person.getId(), List.of()).stream().sorted().toList());
        }
        return people;
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;

/** A person on a sheet. Mutable so an Apply step can change it in place. */
public class Person {

    private final long id;
    private final String sheetId;
    private String name;
    private String grade;
    private List<GradeFrom> grades = List.of();
    private long version;
    private Statements statements = Statements.NONE;
    private LocalDate retiredFrom;
    private List<HoldSpan> holds = List.of();
    private List<String> patrons = List.of();
    private Integer terms;
    private String contact;

    public Person(long id, String sheetId, String name, String grade, long version) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
        this.version = version;
    }

    public long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    /** The grade in force on the sheet's today. */
    public String getGrade() {
        return grade;
    }

    public void setGrade(String grade) {
        this.grade = grade;
    }

    /** The grades the person was given, each from its from-date (the first from the beginning of time). */
    public List<GradeFrom> getGrades() {
        return grades;
    }

    public void setGrades(List<GradeFrom> grades) {
        this.grades = grades;
    }

    /** The grade in force on the date: the one with the latest from-date on or before it, none counting as the earliest. */
    public String gradeOn(LocalDate on) {
        GradeFrom found = null;
        for (GradeFrom g : grades) {
            if (g.from() != null && g.from().isAfter(on)) {
                continue;
            }
            if (found == null || (g.from() != null && (found.from() == null || g.from().isAfter(found.from())))) {
                found = g;
            }
        }
        return found == null ? grade : found.grade();
    }

    /** The person's own terms in days; null when they have none. */
    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    /** The person's contact, trimmed and lower-cased; null when they have none. */
    public String getContact() {
        return contact;
    }

    public void setContact(String contact) {
        this.contact = contact;
    }

    public long getVersion() {
        return version;
    }

    public void setVersion(long version) {
        this.version = version;
    }

    /** The person's statements: how many, and the last one's due-total and date. */
    public Statements getStatements() {
        return statements;
    }

    public void setStatements(Statements statements) {
        this.statements = statements;
    }

    /** The date the person is retired from; null when not retired. Set at all, the person counts as retired. */
    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether the person's retirement date is reached on the date: from then their OPEN and PENDING claims, unless a
     *  statement binds them, count in no live total, as a hold's would. */
    public boolean retiredOn(LocalDate on) {
        return retiredFrom != null && !on.isBefore(retiredFrom);
    }

    /** Whether the person has any hold. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** The person's holds, in the order they were added. */
    public List<HoldSpan> getHolds() {
        return holds;
    }

    public void setHolds(List<HoldSpan> holds) {
        this.holds = holds;
    }

    /** Whether a hold covers the date: the person's OPEN and PENDING claims dated then, unless a statement binds them,
     *  count in no live total. */
    public boolean heldOn(LocalDate on) {
        return holds.stream().anyMatch(h -> h.covers(on));
    }

    /** The names of the person's patrons, sorted. */
    public List<String> getPatrons() {
        return patrons;
    }

    public void setPatrons(List<String> patrons) {
        this.patrons = patrons;
    }
}
package net.officefloor.hq.app.person;

import java.util.List;

/** A person, with the grade in force on the sheet's today and every grade they were given (each from its from-date), their statement count and their last statement's due-total ("n/a" when it had none) and date
 *  (both null before their first statement), the date they are retired from (null: not retired), whether they have any hold and their holds (in the order added), their patrons' names, sorted, their own terms (null: none) and their contact (null: none). */
public record PersonResponse(long id, String name, String grade, List<GradeResponse> grades, long version, int statementCount, String statedTotal,
        String statementDate, String retiredFrom, boolean held, List<HoldResponse> holds,
        List<String> patrons, Integer terms, String contact) {
    public static PersonResponse from(Person person) {
        Statements s = person.getStatements();
        return new PersonResponse(person.getId(), person.getName(), person.getGrade(),
                person.getGrades().stream().map(GradeResponse::from).toList(), person.getVersion(), s.count(),
                s.count() == 0 ? null : s.lastDueTotal() == null ? "n/a" : s.lastDueTotal().toPlainString(),
                s.lastDate() == null ? null : s.lastDate().toString(),
                person.getRetiredFrom() == null ? null : person.getRetiredFrom().toString(), person.isHeld(),
                person.getHolds().stream().map(HoldResponse::from).toList(),
                person.getPatrons(), person.getTerms(), person.getContact());
    }
}

