    public <T> T read(String sheetId, long snapshotId, LocalDate on, Function<JdbcTemplate, T> reader) {
        Connection con = DataSourceUtils.getConnection(dataSource);
        try {
            JdbcTemplate asOf = new JdbcTemplate(new SingleConnectionDataSource(con, true));
            for (String table : TABLES) {
                String columns = columns(asOf, table);
                asOf.update("INSERT INTO asof." + table + " (" + columns + ") SELECT " + columns + " FROM hist." + table
                        + " WHERE snapshot_id = ?", snapshotId);
            }
            asOf.update("UPDATE asof.sheet SET today = ? WHERE id = ?", Date.valueOf(on), sheetId);
            asOf.execute("SET SCHEMA asof");
            try {
                return reader.apply(asOf);
            } finally {
                asOf.execute("SET SCHEMA public");
                for (int i = TABLES.size() - 1; i >= 0; i--) {
                    String table = TABLES.get(i);
                    asOf.update("DELETE FROM asof." + table + " WHERE " + ofSheet(table, "asof"), sheetId);
                }
            }
        } finally {
            DataSourceUtils.releaseConnection(con, dataSource);
        }
    }

    /**
     * Read the sheet as the signed-in user's screen shows it: live when {@code on} is null, else as it stood at the end
     * of that date, the date standing in for the sheet's today. {@code reader} is given a JdbcTemplate over the sheet
     * laid out as the live tables (schema asof), for the app's repositories to read it as they read the live sheet. A
     * date on or after the sheet's today reads every change made; a date before the earliest snapshot reads none.
     * The layout is rolled back once read (to a savepoint inside the request's transaction), so no other request sees it.
     */
    public <T> T view(String sheetId, LocalDate on, Function<JdbcTemplate, T> reader) {
        if (on == null) {
            return reader.apply(jdbc);
        }
        LocalDate today = jdbc.query("SELECT today FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
        Long snapshot = today == null || !on.isBefore(today) ? null : snapshotAsOf(sheetId, on);
        Connection con = DataSourceUtils.getConnection(dataSource);
        try {
            boolean autoCommit = con.getAutoCommit();
            String schema = con.getSchema();
            Savepoint before = autoCommit ? null : con.setSavepoint();
            con.setAutoCommit(false);
            try {
                JdbcTemplate asOf = new JdbcTemplate(new SingleConnectionDataSource(con, true));
                for (String table : TABLES) {
                    String columns = columns(asOf, table);
                    if (snapshot != null) {
                        asOf.update("INSERT INTO asof." + table + " (" + columns + ") SELECT " + columns + " FROM hist."
                                + table + " WHERE snapshot_id = ?", snapshot);
                    } else if (today != null && (!on.isBefore(today) || table.equals("sheet"))) {
                        // On or after its today: every change counts. Before its earliest snapshot: none does.
                        asOf.update("INSERT INTO asof." + table + " (" + columns + ") SELECT " + columns + " FROM public."
                                + table + " WHERE " + ofSheet(table, "public"), sheetId);
                    }
                }
                if (snapshot == null && today != null && on.isBefore(today)) {
                    asOf.update("UPDATE asof.sheet SET archived = FALSE WHERE id = ?", sheetId);
                }
                asOf.update("UPDATE asof.sheet SET today = ? WHERE id = ?", Date.valueOf(on), sheetId);
                con.setSchema("ASOF");
                return reader.apply(asOf);
            } finally {
                con.setSchema(schema);
                if (before == null) {
                    con.rollback();
                    con.setAutoCommit(true);
                } else {
                    con.rollback(before);
                }
            }
        } catch (SQLException e) {
            throw new IllegalStateException("Cannot read the sheet as of " + on, e);
        } finally {
            DataSourceUtils.releaseConnection(con, dataSource);
        }
    }

    /** The table's columns, as the live table lists them. */
    private static String columns(JdbcTemplate jdbc, String table) {
        return String.join(", ", jdbc.queryForList("SELECT column_name FROM information_schema.columns"
                + " WHERE table_schema = 'PUBLIC' AND table_name = ? ORDER BY ordinal_position", String.class,
                table.toUpperCase()));
    }

    /** The condition picking the sheet's rows of the table in the schema (the sheet id its one parameter). */
    private static String ofSheet(String table, String schema) {
        return switch (table) {
            case "sheet" -> "id = ?";
            case "person_grade", "person_hold", "person_patron", "person_watch" ->
                "person_id IN (SELECT id FROM " + schema + ".person WHERE sheet_id = ?)";
            case "period_person_total" -> "period_id IN (SELECT id FROM " + schema + ".period WHERE sheet_id = ?)";
            default -> "sheet_id = ?";
        };
    }
}
-- A sheet as it stood at the end of a run of its todays: taken as the sheet's today moves on from `through` to
-- `until`, it holds every change made while the sheet's today was `through` or earlier, and none made later. A
-- statement as of a date reads the latest snapshot with through <= date < until (see SheetHistory).
CREATE TABLE sheet_snapshot (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    through  DATE         NOT NULL,
    until    DATE         NOT NULL
);
CREATE INDEX sheet_snapshot_sheet ON sheet_snapshot (sheet_id, id);

-- The snapshotted rows: each table a statement's figures read, with the snapshot's id last.
CREATE SCHEMA hist;
CREATE TABLE hist.sheet AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM sheet t WHERE FALSE;
CREATE TABLE hist.person AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person t WHERE FALSE;
CREATE TABLE hist.person_grade AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person_grade t WHERE FALSE;
CREATE TABLE hist.person_hold AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person_hold t WHERE FALSE;
CREATE TABLE hist.person_patron AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person_patron t WHERE FALSE;
CREATE TABLE hist.statement AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM statement t WHERE FALSE;
CREATE TABLE hist.claim AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM claim t WHERE FALSE;
CREATE TABLE hist.rate AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM rate t WHERE FALSE;
CREATE TABLE hist.sheet_setting AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM sheet_setting t WHERE FALSE;
CREATE TABLE hist.sheet_setting_from AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM sheet_setting_from t WHERE FALSE;
CREATE INDEX hist_sheet_snapshot ON hist.sheet (snapshot_id);
CREATE INDEX hist_person_snapshot ON hist.person (snapshot_id);
CREATE INDEX hist_person_grade_snapshot ON hist.person_grade (snapshot_id);
CREATE INDEX hist_person_hold_snapshot ON hist.person_hold (snapshot_id);
CREATE INDEX hist_person_patron_snapshot ON hist.person_patron (snapshot_id);
CREATE INDEX hist_statement_snapshot ON hist.statement (snapshot_id);
CREATE INDEX hist_claim_snapshot ON hist.claim (snapshot_id);
CREATE INDEX hist_rate_snapshot ON hist.rate (snapshot_id);
CREATE INDEX hist_sheet_setting_snapshot ON hist.sheet_setting (snapshot_id);
CREATE INDEX hist_sheet_setting_from_snapshot ON hist.sheet_setting_from (snapshot_id);

-- A snapshot laid out as the live tables, for the length of one request: the repositories read it unchanged with
-- this schema current, the sheet's today standing at the statement's date. Emptied again before the request ends.
